questions.sql:
SELECT staff_id, first_name, last_name, username
  FROM staff
  WHERE BINARY password=SHA('12345');

SELECT title
 FROM film
 WHERE length = (
   SELECT MAX(length)
    FROM film
 );

select f.title
from film f left join film_actor fa on f.film_id = fa.film_id 
where  fa.actor_id  is null;

select l.name 
from `language` l left join film f on l.language_id = f.language_id 
where f.language_id is null;

select c.country, c2.city 
from country c left join city c2 on c.country_id = c2.country_id 
order by c.country, c2.city ;

select c.country, c2.city, a2.address , a2.address2, a2.district 
from country c left join city c2 on c.country_id = c2.country_id left join address a2 on c2.city_id = a2.city_id
order by c.country, c2.city, a2.address;

select a.first_name , a.last_name 
from actor a join customer c2 on a.first_name = c2.first_name and a.last_name = c2.last_name 
order by a.last_name, a.first_name;

SELECT a.first_name , a.last_name , f.title 
FROM actor a LEFT JOIN film_actor fa ON a.actor_id = fa.actor_id 
LEFT JOIN film f  ON fa.film_id = f.film_id;

SELECT DISTINCT c.city 
FROM store s JOIN address a ON s.address_id = a.address_id 
JOIN city c ON a.city_id = c.city_id;

SELECT f.title , f.`length` FROM film f 
WHERE (f.title LIKE 'B%' AND f.`length` > 120)
OR (f.title LIKE '%a%a%' AND f.`length` > 135);

SELECT a.first_name , a.last_name , f.title 
FROM actor a JOIN film_actor fa ON a.actor_id = fa.actor_id 
 JOIN film f  ON fa.film_id = f.film_id;

SELECT title
 FROM film
 WHERE length = (
   SELECT min(length)
    FROM film
 );

SELECT title
FROM film
WHERE rental_rate > (
    SELECT AVG(rental_rate)
    FROM film
);

SELECT city_id
 FROM city
 WHERE country_id=87;

SELECT city_id
 FROM city
 WHERE country_id=34;

SELECT country_id
 FROM country
 WHERE country LIKE 'Spain';

SELECT address_id, address
 FROM address
 WHERE city_id IN (1,146,181,388,459);

SELECT first_name, last_name
 FROM customer
 WHERE customer_id IN (454, 178, 176);

SELECT country_id
 FROM country
 WHERE country like 'France';

SELECT address_id, address
 FROM address
 WHERE city_id IN (92,297,543,544);

select f.title, f.description 
from film f
where description like '%database%' and description like '%Mysql%' and description like '%kill%';

SELECT COUNT(*), SUM(amount)
 FROM payment
 WHERE rental_id IS NULL;

SELECT COUNT(*)
FROM payment
WHERE rental_id IS NULL;

select distinct c2.city 
from customer c join address a on c.address_id = a.address_id join city c2 on a.city_id = c2.city_id 
order by c2.city;

select distinct c2.city 
from staff s join address a on s.address_id = a.address_id join city c2 on a.city_id = c2.city_id 
order by c2.city;
